def wheel_fits(wheel, tag):
    py, abi, plat = wheel.name[:-4].split("-")[-3:]
    if plat != "any" and "linux" not in plat:
        return False
    if abi == "abi3":
        return int(py.split(".")[0][2:]) <= int(tag[2:])
    return any(t.startswith("py3") for t in py.split(".")) or tag in py.split(".")


def norm(name):
    return re.sub(r"[-_.]+", "_", name).lower()


WHEELS = {}
for w in [*(COMP / "wheels").glob("*.whl"), *EXTRA.glob("*.whl"), *PYDS.glob("*.whl")]:
    _n, _v = w.name.split("-")[:2]
    WHEELS.setdefault(norm(_n), []).append((Version(_v), w))

OWN = {"fastapi/fastapi": "fastapi", "Textualize/rich": "rich", "psf/requests": "requests", "encode/httpx": "httpx"}
ONLY_FOR = {"pytest_httpbin": {"psf/requests"}, "httpbin": {"psf/requests"}, "flasgger": {"psf/requests"},
            "brotlicffi": {"psf/requests", "encode/httpx"}, "brotli": {"encode/httpx"}, "zstandard": {"encode/httpx"}}
HOST_TAG = f"cp{sys.version_info.major}{sys.version_info.minor}"
PYTHONS = {HOST_TAG: Path(sys.executable)}
IMAGE_FOLDERS = {}
_BUILD_LOCK = threading.RLock()


def python_exe(tag):
    with _BUILD_LOCK:
        if tag not in PYTHONS:
            ver = f"{tag[2]}.{tag[3:]}"
            dest = SCRATCH / f"py{tag}"
            if not (dest / "python" / "bin" / f"python{ver}").exists():
                with tarfile.open(PYDS / f"cpython-{ver}-linux.tgz.bin", "r:gz") as t:
                    t.extractall(dest)
            PYTHONS[tag] = dest / "python" / "bin" / f"python{ver}"
        return PYTHONS[tag]


def image_folder(repo, tag):
    with _BUILD_LOCK:
        if (repo, tag) in IMAGE_FOLDERS:
            return IMAGE_FOLDERS[(repo, tag)]
        chosen = {}
        for name, options in WHEELS.items():
            options = [(v, w) for v, w in options if wheel_fits(w, tag)]
            if not options or name == OWN[repo] or (name in ONLY_FOR and repo not in ONLY_FOR[name]):
                continue
            from_competition = [(v, w) for v, w in options if w.parent == COMP / "wheels"]
            if name in ("pytest", "pytest_timeout"):
                chosen[name] = next(w for v, w in options if str(v) in ("8.4.2", "2.1.0"))
            elif from_competition:
                chosen[name] = max(from_competition)[1]
            elif name != "pygments":
                chosen[name] = max(options)[1]
        folder = SCRATCH / f"image_{OWN[repo]}_{tag}"
        shutil.rmtree(folder, ignore_errors=True)
        subprocess.run([str(python_exe(tag)), "-m", "pip", "install", "-q", "--no-index", "--no-deps",
                        "--ignore-requires-python", "--target", str(folder), *map(str, chosen.values())])
        for shim in ("imp.py", "telnetlib.py"):
            shutil.copy(COMP / "docker" / shim, folder / shim)
        IMAGE_FOLDERS[(repo, tag)] = (folder, chosen)
        return IMAGE_FOLDERS[(repo, tag)]


