def make_evaluator(arm):
    folder = BUNDLES[arm["bundle"]]
    budget = yaml.safe_load((folder / "eval_config.yaml").read_text())["evaluation"]
    config = EvalConfig(
        tasks_path=COMP / "tasks.jsonl", snapshots_dir=COMP / "snapshots", results_dir=EVAL_ROOT / arm["name"],
        submission_dir=folder, models=models, sandbox="subprocess",
        timeout_seconds=int(budget.get("timeout_seconds", 300)), verification_timeout_seconds=300,
        max_time_minutes=float(budget.get("max_time_minutes", 60)), max_tool_calls=int(budget.get("max_tool_calls", 100)),
        max_turns=budget.get("max_turns"), limits=limits, generation_constraints=gen,
        adapter_manifest=discover_adapters(str(folder), adapter_extensions=ALLOWED_ADAPTER_EXTENSIONS),
        context_cache_config=ContextCacheConfig(min_tokens=2048, ttl_seconds=1800, cache_intervals=10),
        events_compaction_config=EventsCompactionConfig(
            compaction_interval=15, overlap_size=2, token_threshold=14336, event_retention_size=5),
        graph_dir=str(COMP / "graphs"), embeddings_dir=str(COMP / "embeddings"), wheels_dir=COMP / "wheels",
        display_mode="quiet")
    ev = Evaluator(config)
    ev.sandbox = ev.docker = SubprocessManager(
        timeout_seconds=int(budget.get("timeout_seconds", 300)), system_site_packages=False)
    return ev


EVALUATORS = {arm["name"]: make_evaluator(arm) for arm in CFG["arms"]}
RESULTS = WORK / "results.jsonl"
DEADLINE = T0 + 60 * CFG.get("deadline_minutes", 600)
counts = {arm["name"]: [0, 0] for arm in CFG["arms"]}


def variant(arm, tid):
    task = ALL_TASKS[tid]
    hints, meta = apply_level(task.hints_text, arm["level"], task.patch, task.test_patch)
    HINT_META[f'{arm["name"]}/{tid}'] = meta
    return dataclasses.replace(task, hints_text=hints)


async def job(sem, arm, tid, idx, total):
    async with sem:
        row = {"arm": arm["name"], "bundle": arm["bundle"], "level": arm["level"], "task": tid,
               "repo": ALL_TASKS[tid].repo, "gradable": tid in GRADABLE}
        if time.time() > DEADLINE:
            row.update(status="skipped_deadline")
        else:
            CURRENT_TASK.set(tid)
            start = time.time()
            try:
                res = await EVALUATORS[arm["name"]].evaluate_task(task=variant(arm, tid), task_index=idx, total_tasks=total)
                data = _serialize_task_result(res)
                data.pop("agent_patch", None), data.pop("test_output", None)
                row.update(status="done", resolved=bool(res.resolved), tool_calls=res.tool_calls,
                           patch_chars=len(res.agent_patch or ""), result=data)
                await asyncio.to_thread(append_task_result, res, EVAL_ROOT / arm["name"])
            except Exception as exc:  # keep the campaign alive; the row records the failure
                row.update(status="harness_error", error=f"{type(exc).__name__}: {exc}"[:2000],
                           traceback=traceback.format_exc()[-3000:])
            row["seconds"] = round(time.time() - start, 1)
        row["hint"] = HINT_META.get(f'{arm["name"]}/{tid}')
        with open(RESULTS, "a") as f:
            f.write(json.dumps(row, default=str) + "\n")
        c = counts[arm["name"]]
        c[1] += 1
        c[0] += bool(row.get("resolved"))
        log(f'{arm["name"]:>14} {tid:<16} {row["status"]:<14} resolved={row.get("resolved")} '
            f'calls={row.get("tool_calls")} {row.get("seconds")}s | {c[0]}/{c[1]}')


async def main():
    sem = asyncio.Semaphore(CFG.get("concurrency", 8))
    jobs = [(arm, tid) for tid in task_ids for arm in CFG["arms"]]  # task-major: partial runs stay paired
    await asyncio.gather(*(job(sem, arm, tid, i + 1, len(jobs)) for i, (arm, tid) in enumerate(jobs)))


try:
    asyncio.run(main())
except RuntimeError as exc:
    if "running event loop" not in str(exc):
        raise
    from concurrent.futures import ThreadPoolExecutor
    ThreadPoolExecutor(1).submit(asyncio.run, main()).result()
finally:
    try:
        shutil.copy(server.log_path, WORK / "vllm.log")
    except Exception:
        pass
    try:
        server.stop()
    except Exception:
        pass

